use vybe_runtime::{Chunk,Value,VM};
fn compile(s:&str)->Vec<Chunk>{static INIT:std::sync::Once=std::sync::Once::new();INIT.call_once(vybe_language_php::register);let ast=vybe_language_php::parse(&format!("<?php {s}")).unwrap();let p=vybe_compiler::profile::parse_profile(vybe_language_php::profile_source()).unwrap();vybe_compiler::Compiler::with_profile(p).compile(&ast).unwrap()}
fn native(c:&[Chunk],label:&str){let b=vybe_platform_wasm::write_wasm(c);if let Err(e)=wasmparser::Validator::new_with_features(wasmparser::WasmFeatures::all()).validate_all(&b){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("{label}-full-native-failure.wasm"));std::fs::write(p,b).unwrap();panic!("{label} fullnative: {e}");}}
fn run(s:&str,label:&str)->Value{let c=compile(s);native(&c,label);assert!(c.iter().any(|c|c.name=="__stdlib_encoding_bin2hex"),"actual registered helper needed");let mut v=VM::new();vybe_compiler::primitives::platforms::register_platforms_all(&mut v);v.run(c).unwrap()}
#[test]fn actual_ascii_binary_and_scalar_php_controls(){for (s,w) in [("return bin2hex('vybe');","76796265"),("return bin2hex(\"\\x00\\x7f\\x80\\xff\");","007f80ff"),("return bin2hex('');",""),("return bin2hex(123);","313233"),("return bin2hex(true);","31"),("return bin2hex(null);","")]{assert_eq!(run(s,"scalar"),Value::String(w.into()),"{s}");}}
#[test]fn actual_to_string_receiver_and_order(){let s=r#"$trace=''; class CodecInput {public function __toString(){global $trace; $trace.='s'; return "A\x00z";}} $x=new CodecInput(); $answer=bin2hex($x); return $answer.':'.$trace;"#;assert_eq!(run(s,"tostring"),Value::String("41007a:s".into()));}
#[test]fn actual_to_string_throw_and_partial_trace(){let s=r#"$trace=''; class CodecFail {public function __toString(){global $trace; $trace.='s'; throw new Exception('codec-stop');}} try {bin2hex(new CodecFail()); return 'wrong';} catch(Exception $e){return $trace.':'.$e->getMessage();}"#;assert_eq!(run(s,"throw"),Value::String("s:codec-stop".into()));}
